import { useEffect, useMemo } from 'react';
import { useIntl } from 'react-intl';

import { Cover } from 'components';
import { usePageIndexes } from 'hooks';
import { StyledExportPageSection } from 'shared/Styles/exportPages.styles';

import { pageSections, UNIFIED_GLOBAL_SLIDES } from '../../../constants';
import { buildCoverPeriod } from '../../../helpers';
import type { buildGlobalDataForPeriod } from '../../../hooks/usePowerBookGlobalData/usePowerBookGlobalData';
import { usePowerBookPeriods } from '../../../hooks/usePowerBookPeriods/usePowerBookPeriods';
import { InsightRecord } from '../../../types';
import { LazySlide } from '../../LazySlide';
import {
  getSlideId,
  renderSlideByType,
  type SlideRenderContext,
} from './slideRenderers';

const YTD_SLIDES = UNIFIED_GLOBAL_SLIDES.filter((s) => s.type !== 'evolution');

type GlobalPeriodData = ReturnType<typeof buildGlobalDataForPeriod>;

interface GlobalViewProps {
  containerRef: React.RefObject<HTMLElement>;
  qtdData: GlobalPeriodData;
  ytdData: GlobalPeriodData;
  isCompleteBook?: boolean;
  insightsData: InsightRecord[];
}

export const GlobalView = ({
  containerRef,
  qtdData,
  ytdData,
  isCompleteBook,
  insightsData,
}: GlobalViewProps) => {
  const { formatMessage } = useIntl();
  const { getPageByName, updateIndexes } = usePageIndexes(containerRef);
  const { qtdPeriod, ytdPeriod, qtdCoverPrefix, qtdCoverYear, fiscalYear } =
    usePowerBookPeriods();

  const qtdCoverPeriod = useMemo(
    () => buildCoverPeriod(qtdCoverPrefix, qtdCoverYear),
    [qtdCoverPrefix, qtdCoverYear],
  );
  const ytdCoverPeriod = useMemo(
    () => buildCoverPeriod('YTD', fiscalYear, qtdCoverPrefix),
    [fiscalYear, qtdCoverPrefix],
  );

  useEffect(() => {
    updateIndexes();
  }, [updateIndexes, isCompleteBook]);

  const renderSlides = (
    slides: readonly (typeof UNIFIED_GLOBAL_SLIDES)[number][],
    globalData: GlobalPeriodData,
    sectionSuffix: string,
    period: string,
    coverPeriod: React.ReactNode,
    selectedPeriodType: 'QTD' | 'YTD',
  ) => {
    const ctx: SlideRenderContext = {
      globalData,
      sectionSuffix,
      period,
      coverPeriod,
      getPageByName,
      formatMessage,
      selectedPeriodType,
      insights: insightsData,
    };

    return slides.map((config) => {
      const slideId = getSlideId(config, sectionSuffix);
      const lazyChildren = renderSlideByType(config, ctx);

      if (!lazyChildren) return null;

      return (
        <LazySlide key={slideId} id={slideId}>
          {lazyChildren}
        </LazySlide>
      );
    });
  };

  return (
    <>
      {renderSlides(
        UNIFIED_GLOBAL_SLIDES,
        qtdData,
        '',
        qtdPeriod,
        qtdCoverPeriod,
        'QTD',
      )}

      <LazySlide
        key={pageSections.coverYtdResults}
        id={pageSections.coverYtdResults}
      >
        <StyledExportPageSection data-page-name={pageSections.coverYtdResults}>
          <Cover
            category="One Way Reports"
            name="Brand Power Book"
            countries={[{ code: 'ABI', name: 'Global' }]}
            loading={false}
            period={ytdCoverPeriod}
            showLogo
          />
        </StyledExportPageSection>
      </LazySlide>

      {renderSlides(
        YTD_SLIDES,
        ytdData,
        '-ytd',
        ytdPeriod,
        ytdCoverPeriod,
        'YTD',
      )}
    </>
  );
};
